const params=new URLSearchParams(location.search);if(params.has("highlight"))try{await import("/pagefind/pagefind-highlight.js"),new PagefindHighlight({highlightParam:"highlight",markContext:"[data-pagefind-body]",markOptions:{className:"pagefind-highlight",exclude:["[data-pagefind-ignore]","[data-pagefind-ignore] *"]},addStyles:!1})}catch(t){console.warn("[pagefind] highlight unavailable:",t);const e=new URL(location.href);e.searchParams.delete("highlight"),history.replaceState(null,"",e.toString())}